import './styles/App.css';
import './styles/reset.css';
import { useState, useEffect, useRef} from 'react';

import {makeRequest} from './api/api'
import SideMenu from './components/SideMenu/SideMenu'
import ChatMessage from './components/ChatMessage/ChatMessage'

function App() {

  const [input, setInput] = useState("")
  const [chatLog, setChatLog] = useState([{
    user: "gpt",
    message:"Como posso te ajudar hoje?"
  }])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState(null)
  const [conversations, setConversations] = useState([])
  const [currentConversationId, setCurrentConversationId] = useState(null)
  const chatLogRef = useRef(null)


  // Carrega conversas do localStorage ao iniciar
  useEffect(() => {
    const saved = localStorage.getItem('chatgpt-conversations')
    if (saved) {
      const parsed = JSON.parse(saved)
      setConversations(parsed)
      if (parsed.length > 0) {
        const lastConv = parsed[parsed.length - 1]
        setCurrentConversationId(lastConv.id)
        setChatLog(lastConv.messages)
      }
    }
  }, [])

  // Salva conversas no localStorage sempre que mudam
  useEffect(() => {
    if (conversations.length > 0) {
      localStorage.setItem('chatgpt-conversations', JSON.stringify(conversations))
    }
  }, [conversations])

  // Atualiza conversa atual quando chatLog muda
  useEffect(() => {
    if (currentConversationId && chatLog.length > 1) {
      setConversations(prev => 
        prev.map(conv => 
          conv.id === currentConversationId 
            ? { ...conv, messages: chatLog, updatedAt: new Date().toISOString() }
            : conv
        )
      )
    }
  }, [chatLog, currentConversationId])


  async function handleSubmit(e) {
    e.preventDefault();

    if (!input.trim()) return;

    setError(null);
    setIsLoading(true);

    // Adiciona mensagem do usuário imediatamente
    const newChatLog = [...chatLog, {
      user: 'me', 
      message: input
    }];
    setChatLog(newChatLog);
    const currentInput = input;
    setInput("");

    try {
      let response = await makeRequest(currentInput)

      setChatLog([...newChatLog, {
        user: 'gpt', 
        message: response.data
      }])
    } catch (err) {
      console.error('Error:', err);
      setError('Desculpe, ocorreu um erro ao processar sua mensagem. Tente novamente.');
      setChatLog([...newChatLog, {
        user: 'gpt', 
        message: 'Desculpe, ocorreu um erro ao processar sua mensagem. Tente novamente.'
      }])
    } finally {
      setIsLoading(false);
    }
  }

  async function handleRegenerateResponse() {
    if (chatLog.length < 2) return;

    // Pega a última pergunta do usuário
    let lastUserMessage = null;
    for (let i = chatLog.length - 1; i >= 0; i--) {
      if (chatLog[i].user === 'me') {
        lastUserMessage = chatLog[i].message;
        break;
      }
    }

    if (!lastUserMessage) return;

    // Remove última resposta do GPT
    const newChatLog = chatLog.filter((msg, idx) => 
      idx !== chatLog.length - 1 || msg.user !== 'gpt'
    );

    setChatLog(newChatLog);
    setIsLoading(true);
    setError(null);

    try {
      let response = await makeRequest(lastUserMessage)

      setChatLog([...newChatLog, {
        user: 'gpt', 
        message: response.data
      }])
    } catch (err) {
      console.error('Error:', err);
      setChatLog([...newChatLog, {
        user: 'gpt', 
        message: 'Desculpe, ocorreu um erro ao processar sua mensagem. Tente novamente.'
      }])
    } finally {
      setIsLoading(false);
    }
  }

  function handleNewChat() {
    const newConvId = Date.now()
    const initialMessage = {
      user: "gpt",
      message:"Como posso te ajudar hoje?"
    }

    const newConversation = {
      id: newConvId,
      title: 'Nova conversa',
      messages: [initialMessage],
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    }

    setConversations(prev => [...prev, newConversation])
    setCurrentConversationId(newConvId)
    setChatLog([initialMessage]);
    setInput("");
    setError(null);
  }

  function handleSelectConversation(convId) {
    const conv = conversations.find(c => c.id === convId)
    if (conv) {
      setCurrentConversationId(convId)
      setChatLog(conv.messages)
      setInput("")
      setError(null)
    }
  }

  function handleDeleteConversation(convId) {
    setConversations(prev => prev.filter(c => c.id !== convId))

    if (currentConversationId === convId) {
      const remaining = conversations.filter(c => c.id !== convId)
      if (remaining.length > 0) {
        handleSelectConversation(remaining[remaining.length - 1].id)
      } else {
        handleNewChat()
      }
    }
  }

  // Scroll automático para última mensagem
  useEffect(() => {
    if (chatLogRef.current) {
      chatLogRef.current.scrollTop = chatLogRef.current.scrollHeight;
    }
  }, [chatLog]);

  return (
    <div className='App'>

      <SideMenu 
        onNewChat={handleNewChat}
        conversations={conversations}
        currentConversationId={currentConversationId}
        onSelectConversation={handleSelectConversation}
        onDeleteConversation={handleDeleteConversation}
      />

      <section className='chatbox'>

          <div className='chat-log' ref={chatLogRef}>
            {chatLog.map((message, index)=>(
              <ChatMessage key={index} message={message} />
            ))}
            {isLoading && (
              <ChatMessage 
                message={{
                  user: 'gpt',
                  message: 'Digitando...'
                }} 
              />
            )}
          </div>

          <div className='chat-input-holder'>
            {chatLog.length > 2 && chatLog[chatLog.length - 1].user === 'gpt' && !isLoading && (
              <button 
                className='regenerate-button'
                onClick={handleRegenerateResponse}
              >
                🔄 Regenerar resposta
              </button>
            )}
            <form onSubmit={handleSubmit}>
              <input
                rows='1'
                className='chat-input-textarea'
                placeholder='Envie uma mensagem...'
                value={input}
                onChange={e =>setInput(e.target.value)}
                disabled={isLoading}
              >
              </input>
            </form>
          </div>
      </section>

    </div>
  );
}

export default App;
